from collections import deque


def fewest_breaks(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    cost = [[float("inf")] * cols for _ in range(rows)]
    cost[0][0] = 0
    dq = deque([(0, 0)])
    while dq:
        r, c = dq.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                w = 1 if grid[nr][nc] == "#" else 0
                if cost[r][c] + w < cost[nr][nc]:
                    cost[nr][nc] = cost[r][c] + w
                    if w:
                        dq.append((nr, nc))          # one more break: back of the line
                    else:
                        dq.appendleft((nr, nc))      # free step: same cost, front
    return cost[rows - 1][cols - 1]

