def fewest_breaks(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    cost = [[float("inf")] * cols for _ in range(rows)]
    cost[0][0] = 0
    changed = True
    while changed:                               # sweep every cell until nothing improves
        changed = False
        for r in range(rows):
            for c in range(cols):
                w = 1 if grid[r][c] == "#" else 0
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and cost[nr][nc] + w < cost[r][c]:
                        cost[r][c] = cost[nr][nc] + w
                        changed = True
    return cost[rows - 1][cols - 1]
